/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                                     //
// client/Templates/pages/pharmacy_list.js                                                                             //
//                                                                                                                     //
/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                                                                                                                       //
let Template;
module.watch(require("meteor/templating"), {
  Template(v) {
    Template = v;
  }

}, 0);
module.watch(require("./pharmacy_list.html"));
Template.pharmaciesPage.helpers({
  pharmacies() {
    const params = new URLSearchParams(window.location.search);
    const ville = params.get('ville');
    const garde = params.get('garde') === 'true';
    let filters = {};
    if (ville) filters.ville = ville;
    if (params.has('garde')) filters.garde = garde;
    return Shop.find(filters).fetch();
  }

});
